{"file_path":"src/cli.js","old_string":"// Resolve a region
function resolveRegion(base, region) {
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')

  if (mineChanges.length === 0) {
    // Only theirs changed
    return {
      type: 'theirs',
      lines: theirsChanges.length > 0 ? theirsChanges[0].sideLines : []
    }
  }

  if (theirsChanges.length === 0) {
    // Only mine changed
    return {
      type: 'mine',
      lines: mineChanges[0].sideLines
    }
  }

  // Both sides changed
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  const mineStart = Math.min(...mineChanges.map(c => c.baseStart))
  const mineEnd = Math.max(...mineChanges.map(c => c.baseEnd))
  const theirsStart = Math.min(...theirsChanges.map(c => c.baseStart))
  const theirsEnd = Math.max(...theirsChanges.map(c => c.baseEnd))

  // Collect mine's lines
  const mineLines = []
  const backStart = mineStart - region.baseStart
  const forwardEnd = mineEnd - region.baseStart

  for (const change of mineChanges) {
    const offset = change.baseStart - region.baseStart
    mineLines.push(...change.sideLines)
  }

  // Collect theirs's lines
  const theirsLines = []
  for (const change of theirsChanges) {
    theirsLines.push(...change.sideLines)
  }

  // Check for conflicts
  const mineStr = mineLines.join('\n')
  const theirsStr = theirsLines.join('\n')
  const baseStr = baseLines.join('\n')

  if (mineStr === theirsStr) {
    return { type: 'both', lines: mineLines }
  }

  if (mineStr === baseStr) {
    return { type: 'theirs', lines: theirsLines }
  }

  if (theirsStr === baseStr) {
    return { type: 'mine', lines: mineLines }
  }

  // Conflict
  return {
    type: 'conflict',
    mineLines,
    baseLines,
    theirsLines
  }
}","new_string":"// Reconstruct lines for a side within a region
function reconstructLines(base, changes, region) {
  const lines = []
  const changeMap = new Map()

  // Map base positions to changes
  for (const change of changes) {
    changeMap.set(change.baseStart, change)
  }

  let pos = region.baseStart
  while (pos < region.baseEnd) {
    const change = changeMap.get(pos)
    if (change) {
      lines.push(...change.sideLines)
      pos = change.baseEnd
    } else {
      lines.push(base[pos])
      pos++
    }
  }

  return lines
}

// Resolve a region
function resolveRegion(base, region) {
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')

  if (mineChanges.length === 0) {
    // Only theirs changed
    const lines = reconstructLines(base, theirsChanges, region)
    return {
      type: 'theirs',
      lines
    }
  }

  if (theirsChanges.length === 0) {
    // Only mine changed
    const lines = reconstructLines(base, mineChanges, region)
    return {
      type: 'mine',
      lines
    }
  }

  // Both sides changed
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  const mineLines = reconstructLines(base, mineChanges, region)
  const theirsLines = reconstructLines(base, theirsChanges, region)

  // Check for conflicts
  const mineStr = mineLines.join('\n')
  const theirsStr = theirsLines.join('\n')
  const baseStr = baseLines.join('\n')

  if (mineStr === theirsStr) {
    return { type: 'both', lines: mineLines }
  }

  if (mineStr === baseStr) {
    return { type: 'theirs', lines: theirsLines }
  }

  if (theirsStr === baseStr) {
    return { type: 'mine', lines: mineLines }
  }

  // Conflict
  return {
    type: 'conflict',
    mineLines,
    baseLines,
    theirsLines
  }
}"}

