{"file_path":"src/diff3.js","content":"/**
 * Three-way merge over whole lines.
 */

/**
 * Longest common subsequence of two line arrays, as a list of matched index
 * pairs. Ties are broken by taking the matches that come earliest: walking both
 * documents from the start, a match is taken whenever the two current lines are
 * equal, otherwise the side whose remaining subsequence is at least as long as
 * the other's advances, with the base (the first argument) preferred on a tie.
 */
export function lcsPairs(a, b) {
  const m = a.length
  const n = b.length
  // suffix[i][j] = length of the LCS of a[i..] and b[j..]
  const suffix = new Array(m + 1)
  for (let i = 0; i <= m; i++) suffix[i] = new Int32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    const row = suffix[i]
    const next = suffix[i + 1]
    for (let j = n - 1; j >= 0; j--) {
      row[j] = a[i] === b[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }

  const pairs = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (a[i] === b[j]) {
      pairs.push([i, j])
      i++
      j++
    } else if (suffix[i + 1][j] >= suffix[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return pairs
}

/**
 * The stretches the common subsequence does not cover, each a run of base lines
 * replaced by a run of the side's lines.
 */
export function changes(base, side) {
  const pairs = lcsPairs(base, side)
  const result = []
  let baseIdx = 0
  let sideIdx = 0
  for (let k = 0; k <= pairs.length; k++) {
    const nextBase = k < pairs.length ? pairs[k][0] : base.length
    const nextSide = k < pairs.length ? pairs[k][1] : side.length
    if (baseIdx < nextBase || sideIdx < nextSide) {
      result.push({
        baseStart: baseIdx,
        baseEnd: nextBase,
        sideStart: sideIdx,
        sideEnd: nextSide,
      })
    }
    baseIdx = nextBase + 1
    sideIdx = nextSide + 1
  }
  return result
}

function spanLines(doc, own, region) {
  if (own.length === 0) return null
  let minBase = Infinity
  let maxBase = -Infinity
  let minSide = Infinity
  let maxSide = -Infinity
  for (const c of own) {
    if (c.baseStart < minBase) minBase = c.baseStart
    if (c.baseEnd > maxBase) maxBase = c.baseEnd
    if (c.sideStart < minSide) minSide = c.sideStart
    if (c.sideEnd > maxSide) maxSide = c.sideEnd
  }
  const start = minSide - (minBase - region.start)
  const end = maxSide + (region.end - maxBase)
  return doc.slice(start, end)
}

const same = (x, y) => x.length === y.length && x.every((v, i) => v === y[i])

/**
 * The regions of the merge, in order: stable stretches of base together with
 * the resolved or conflicting regions the changes carve out.
 */
export function mergeRegions(mine, base, theirs) {
  const all = []
  for (const c of changes(base, mine)) all.push({ ...c, side: 'mine' })
  for (const c of changes(base, theirs)) all.push({ ...c, side: 'theirs' })
  all.sort((x, y) => {
    if (x.baseStart !== y.baseStart) return x.baseStart - y.baseStart
    if (x.side === y.side) return 0
    return x.side === 'mine' ? -1 : 1
  })

  const groups = []
  let idx = 0
  while (idx < all.length) {
    const first = all[idx++]
    const group = { start: first.baseStart, end: first.baseEnd, list: [first] }
    while (idx < all.length && all[idx].baseStart <= group.end) {
      const next = all[idx++]
      if (next.baseEnd > group.end) group.end = next.baseEnd
      group.list.push(next)
    }
    groups.push(group)
  }

  const regions = []
  let pos = 0
  for (const group of groups) {
    if (pos < group.start) {
      regions.push({ type: 'stable', lines: base.slice(pos, group.start) })
    }
    const baseLines = base.slice(group.start, group.end)
    const mineLines =
      spanLines(mine, group.list.filter(c => c.side === 'mine'), group) ?? baseLines
    const theirsLines =
      spanLines(theirs, group.list.filter(c => c.side === 'theirs'), group) ?? baseLines

    if (same(mineLines, theirsLines)) {
      regions.push({ type: 'both', lines: mineLines })
    } else if (same(mineLines, baseLines)) {
      regions.push({ type: 'theirs', lines: theirsLines })
    } else if (same(theirsLines, baseLines)) {
      regions.push({ type: 'mine', lines: mineLines })
    } else {
      regions.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }
    pos = group.end
  }
  if (pos < base.length) {
    regions.push({ type: 'stable', lines: base.slice(pos) })
  } else if (groups.length === 0) {
    regions.push({ type: 'stable', lines: [] })
  }
  return regions
}

export function render(regions, mode) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.type === 'conflict') {
      conflict = true
      if (mode === 'regions') {
        out.push(
          `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`,
        )
      } else {
        out.push('<<<<<<< mine')
        out.push(...region.mine)
        if (mode === 'merge') {
          out.push('||||||| base')
          out.push(...region.base)
        }
        out.push('=======')
        out.push(...region.theirs)
        out.push('>>>>>>> theirs')
      }
    } else if (mode === 'regions') {
      out.push(`${region.type} ${region.lines.length}`)
    } else {
      out.push(...region.lines)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflict }
}
"}

