 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'fs'

// Parse command line arguments
const mode = process.argv[2]
if (!mode || !['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}

// Read stdin
const input = readFileSync(0, 'utf8')

// Parse input into three documents
function parseInput(text) {
  const lines = text.split('\n')
  // Remove trailing empty line if present
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  // Find %%% separators
  const separatorIndices = []
  for (let i = 0; i < lines.length; i++) {
    if (lines[i] === '%%%') {
      separatorIndices.push(i)
    }
  }

  if (separatorIndices.length !== 2) {
    process.stderr.write('error: expected three parts separated by %%%\n')
    process.exit(2)
  }

  const mine = lines.slice(0, separatorIndices[0])
  const base = lines.slice(separatorIndices[0] + 1, separatorIndices[1])
  const theirs = lines.slice(separatorIndices[1] + 1)

  return { mine, base, theirs }
}

// Calculate LCS using dynamic programming with tie-breaking
// When two paths have equal length, prefer the one whose matches come earliest
function lcs(a, b) {
  const m = a.length
  const n = b.length

  // dp[i][j] = length of LCS for a[0..i-1] and b[0..j-1]
  const dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0))

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
      }
    }
  }

  // Backtrack to find the actual LCS indices with tie-breaking
  // Prefer advancing from a (base) when tie, then from b (other side)
  const aIndices = []
  const bIndices = []

  let i = m
  let j = n

  while (i > 0 && j > 0) {
    if (a[i - 1] === b[j - 1]) {
      aIndices.unshift(i - 1)
      bIndices.unshift(j - 1)
      i--
      j--
    } else {
      // When tie, prefer advancing from the side with longer remaining sequence
      // to get earliest matches
      const aRemaining = i - 1
      const bRemaining = j - 1

      if (aRemaining >= bRemaining) {
        i--
      } else {
        j--
      }
    }
  }

  return { aIndices, bIndices }
}

// Find changes in a side compared to base
function findChanges(base, side, lcsResult) {
  const changes = []
  let baseIdx = 0
  let sideIdx = 0
  let lcsIdx = 0

  while (lcsIdx <= lcsResult.aIndices.length) {
    const nextBaseIdx = lcsIdx < lcsResult.aIndices.length ? lcsResult.aIndices[lcsIdx] : base.length
    const nextSideIdx = lcsIdx < lcsResult.bIndices.length ? lcsResult.bIndices[lcsIdx] : side.length

    // If there's a gap, record the change
    if (baseIdx < nextBaseIdx || sideIdx < nextSideIdx) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: nextBaseIdx,
        baseLines: base.slice(baseIdx, nextBaseIdx),
        sideStart: sideIdx,
        sideEnd: nextSideIdx,
        sideLines: side.slice(sideIdx, nextSideIdx)
      })
    }

    baseIdx = nextBaseIdx + 1
    sideIdx = nextSideIdx + 1
    lcsIdx++
  }

  return changes
}

// Merge regions that overlap
function mergeRegions(mineChanges, theirsChanges) {
  const allChanges = []

  for (const change of mineChanges) {
    allChanges.push({ ...change, side: 'mine' })
  }

  for (const change of theirsChanges) {
    allChanges.push({ ...change, side: 'theirs' })
  }

  // Sort by baseStart, then by side (mine before theirs)
  allChanges.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let currentRegion = null

  for (const change of allChanges) {
    if (!currentRegion) {
      currentRegion = {
        baseStart: change.baseStart,
        baseEnd: change.baseEnd,
        changes: [change]
      }
    } else if (change.baseStart <= currentRegion.baseEnd) {
      // Overlap: extend region
      currentRegion.baseEnd = Math.max(currentRegion.baseEnd, change.baseEnd)
      currentRegion.changes.push(change)
    } else {
      // No overlap: start new region
      regions.push(currentRegion)
      currentRegion = {
        baseStart: change.baseStart,
        baseEnd: change.baseEnd,
        changes: [change]
      }
    }
  }

  if (currentRegion) {
    regions.push(currentRegion)
  }

  return regions
}

// Reconstruct lines for a side within a region
function reconstructLines(base, changes, region) {
  const lines = []
  const changeMap = new Map()

  // Map base positions to changes
  for (const change of changes) {
    changeMap.set(change.baseStart, change)
  }

  let pos = region.baseStart
  while (pos <= region.baseEnd) {
    const change = changeMap.get(pos)
    if (change) {
      lines.push(...change.sideLines)
      // For insertions (baseStart == baseEnd), move to next position
      if (change.baseStart === change.baseEnd) {
        pos++
      } else {
        pos = change.baseEnd
      }
    } else if (pos < region.baseEnd) {
      lines.push(base[pos])
      pos++
    } else {
      break
    }
  }

  return lines
}

// Resolve a region
function resolveRegion(base, region) {
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')

  if (mineChanges.length === 0) {
    // Only theirs changed
    const lines = reconstructLines(base, theirsChanges, region)
    return {
      type: 'theirs',
      lines
    }
  }

  if (theirsChanges.length === 0) {
    // Only mine changed
    const lines = reconstructLines(base, mineChanges, region)
    return {
      type: 'mine',
      lines
    }
  }

  // Both sides changed
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  const mineLines = reconstructLines(base, mineChanges, region)
  const theirsLines = reconstructLines(base, theirsChanges, region)

  // Check for conflicts
  const mineStr = mineLines.join('\n')
  const theirsStr = theirsLines.join('\n')
  const baseStr = baseLines.join('\n')

  if (mineStr === theirsStr) {
    return { type: 'both', lines: mineLines }
  }

  if (mineStr === baseStr) {
    return { type: 'theirs', lines: theirsLines }
  }

  if (theirsStr === baseStr) {
    return { type: 'mine', lines: mineLines }
  }

  // Conflict
  return {
    type: 'conflict',
    mineLines,
    baseLines,
    theirsLines
  }
}

// Main merge logic
const { mine, base, theirs } = parseInput(input)

const lcsMineBased = lcs(base, mine)
const lcsTheirsBased = lcs(base, theirs)

const mineChanges = findChanges(base, mine, lcsMineBased)
const theirsChanges = findChanges(base, theirs, lcsTheirsBased)

const regions = mergeRegions(mineChanges, theirsChanges)

// Generate stable regions
const stableRegions = []

if (regions.length === 0) {
  // No regions: entire base is stable
  stableRegions.push({
    type: 'stable',
    baseStart: 0,
    baseEnd: base.length,
    lines: base
  })
} else {
  let pos = 0
  for (const region of regions) {
    if (pos < region.baseStart) {
      stableRegions.push({
        type: 'stable',
        baseStart: pos,
        baseEnd: region.baseStart,
        lines: base.slice(pos, region.baseStart)
      })
    }

    const resolved = resolveRegion(base, region)
    stableRegions.push({
      type: resolved.type,
      baseStart: region.baseStart,
      baseEnd: region.baseEnd,
      ...resolved
    })

    pos = region.baseEnd
  }

  if (pos < base.length) {
    stableRegions.push({
      type: 'stable',
      baseStart: pos,
      baseEnd: base.length,
      lines: base.slice(pos)
    })
  }
}

// Output
let hasConflict = false
const output = []

if (mode === 'regions') {
  for (const region of stableRegions) {
    const count = region.lines ? region.lines.length : (region.mineLines ? region.mineLines.length : 0)
    if (region.type === 'conflict') {
      hasConflict = true
      output.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else if (region.type === 'stable') {
      output.push(`stable ${region.lines.length}`)
    } else if (region.type === 'both') {
      output.push(`both ${region.lines.length}`)
    } else {
      output.push(`${region.type} ${region.lines.length}`)
    }
  }
} else {
  for (const region of stableRegions) {
    if (region.type === 'conflict') {
      hasConflict = true
      output.push('<<<<<<< mine')
      output.push(...region.mineLines)
      if (mode === 'merge') {
        output.push('||||||| base')
        output.push(...region.baseLines)
      }
      output.push('=======')
      output.push(...region.theirsLines)
      output.push('>>>>>>> theirs')
    } else {
      output.push(...region.lines)
    }
  }
}

process.stdout.write(output.map(line => line + '\n').join(''))
process.exit(hasConflict ? 1 : 0)

